import{_ as t,o,c as n,a3 as c}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Clients","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/clients.md","filePath":"dev/domain/clients.md"}'),i={name:"dev/domain/clients.md"};function d(a,e,s,r,l,h){return o(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h1><p>The <strong>Clients</strong> module owns client accounts and their relationship to centers.</p><h2 id="sign-in-and-registration" tabindex="-1">Sign-in and registration <a class="header-anchor" href="#sign-in-and-registration" aria-label="Permalink to &quot;Sign-in and registration&quot;">​</a></h2><p>Clients are created <strong>by OTP verify</strong> or <strong>by a center</strong>. In the app, <code>POST clients/auth/login</code> sends a code and <code>POST clients/auth/verify</code> checks it; the account is created through <code>ClientAuthService::findOrCreateByPhone</code> after a successful verify. A center creates a client without an account through <code>CenterClientService::create</code> (see below). Both fire <code>ClientRegistered</code>. See <a href="./support">Support</a> for OTP rules.</p><p>A client <strong>needs onboarding</strong> while <code>first_name</code> or <code>last_name</code> is null. <code>PUT clients/profile</code> completes the profile; <code>GET clients/me</code> returns the current client.</p><p>A client changes their phone in two steps, both through <code>OtpVerificationService</code> with the login limits: <code>POST clients/phone</code> sends a code to the <strong>new</strong> phone and <code>POST clients/phone/verify</code> checks it, then <code>ClientAuthService::changePhone</code> saves it. The new phone must differ from the current one and must not belong to another non-deleted client; this is validated on both steps and re-checked under lock on save, because <code>clients.phone_number</code> has no unique index. The current token stays valid and the next login uses the new phone.</p><p><code>POST clients/launch</code> must be called on every app start (30 per minute). It registers or refreshes the device with its FCM token, platform and locale. Without a token the device is stored unlinked and linked on verify when the same <code>device_identifier</code> is sent.</p><p><code>GET clients/bookings</code> is one feed of reservations, packages and memberships, newest first.</p><h2 id="relationship-to-centers" tabindex="-1">Relationship to centers <a class="header-anchor" href="#relationship-to-centers" aria-label="Permalink to &quot;Relationship to centers&quot;">​</a></h2><ul><li>A center sees only clients in <code>center_client</code>, or with a Confirmed or Completed purchase where it is the merchant. Never list clients across centers.</li><li>A center can <strong>block</strong> a client (<code>POST …/blocked-clients</code>) and unblock them again (<code>DELETE …/blocked-clients/{client}</code>, 404 when the center has not blocked that client). Blocked clients cannot book that center.</li><li>Clients are <strong>soft-deleted</strong>; raw queries must filter <code>deleted_at</code>.</li><li><strong>Desk lookup and creation</strong> (<code>centers/{center}/clients</code>, also under <code>admin/centers/{center}/clients</code>; <code>manageReservations</code>): <ul><li><code>GET …/lookup?phone_number=</code> is an exact match on <code>phone_number</code> across <strong>all</strong> clients, so the desk can book a client new to the center. Phones are stored as the client typed them at login (for example <code>+966500000003</code>), so the input must match that form. It returns <code>{id, first_name, last_name, phone_number}</code>, or 404 when no client has that phone (deleted clients are ignored). It does not add the client to the center.</li><li><code>POST …</code> with <code>phone_number</code>, <code>first_name</code> and <code>last_name</code> creates a client under lock (the phone has no unique index; a taken phone is a 422 <code>validation.phone_taken</code>), adds them to <code>center_client</code> and fires <code>ClientRegistered</code> after commit. The client can later sign in by OTP with the same phone and keeps the same account, with onboarding already complete.</li></ul></li></ul><h2 id="favorites-and-ratings" tabindex="-1">Favorites and ratings <a class="header-anchor" href="#favorites-and-ratings" aria-label="Permalink to &quot;Favorites and ratings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Notes</th></tr></thead><tbody><tr><td><code>GET/POST clients/favorites</code>, <code>DELETE clients/favorites/{center}</code></td><td>Favorite centers</td></tr><tr><td><code>POST clients/ratings</code></td><td>Rate a center. Aggregates feed center lists and <code>top_centers</code>.</td></tr><tr><td><code>GET clients/ratings</code></td><td>The client&#39;s own center ratings, 15 per page. <code>sort</code> (<code>RatingController::SORTS</code>): <code>newest</code> (default) or <code>highest</code> (most stars first, then newest).</td></tr><tr><td><code>PATCH clients/ratings/{rating}</code></td><td>Edit the <code>stars</code> and/or <code>comment</code> of one of the client&#39;s own ratings (404 otherwise); omitted fields keep their value. Goes through <code>RatingService::update</code> and flushes the center search cache.</td></tr></tbody></table><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><p><code>admin/clients</code> (list, show, search, export) with <code>clients.view_any</code>, <code>clients.view</code> and <code>clients.export</code>.</p><p>The list and export take <code>sort</code> (<code>AdminClientQuery::SORTS</code>): <code>name</code> (first, then last name), <code>created_at</code>, <code>centers_count</code> or <code>reservations_count</code>, <code>-</code> for descending; newest first without it. See <a href="./../conventions/coding#list-sorting">List sorting</a>.</p><p><code>POST admin/clients/{client}/otp</code> with <code>otps.create</code> issues a login code for the client and returns it once, without an SMS. See <a href="./support#admin-issued-codes">Support: OTP</a>.</p>',16)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
